# Single-cell 9 locations: (3,15), (10,11), (16,8), (18,12)
# Grid cells these are in: (0,2), (1,1), (2,1), (1,1) [note (1,1) has TWO marker]

horiz_boundaries = [-1, 6, 17, 19, 22]
vert_boundaries = [-1, 4, 13, 24, 28, 29]

# Let me list all grid cells and see which have markers
# Grid cells = intervals between landmark lines
print("Grid cells defined by landmark lines:")
for hi, h1 in enumerate(horiz_boundaries[:-1]):
    r_labels = ["edge", "interior"]
    if h1 >= 0:
        r_labels[0] = "interior"  # Above landmark 6
    for vi, v1 in enumerate(vert_boundaries[:-1]):
        if h1 >= 0 and v1 >= 0:
            print(f"Cell ({hi},{vi}): rows {h1}-{horiz_boundaries[hi+1]}, cols {v1}-{vert_boundaries[vi+1]}")

# Markers: (3,15) -> (0,2), (10,11) -> (1,1), (16,8) -> (1,1), (18,12) -> (2,1)
marker_cells = {find_grid_cell(3, 15), find_grid_cell(10, 11), find_grid_cell(16, 8), find_grid_cell(18, 12)}
print(f"\nMarker cells: {marker_cells}")

def find_grid_cell(r, c):
    hi = None
    for i, h in enumerate(horiz_boundaries):
        if h < r < horiz_boundaries[i+1]:
            hi = i
            break
    vi = None
    for i, v in enumerate(vert_boundaries):
        if v < c < vert_boundaries[i+1]:
            vi = i
            break
    return (hi, vi)

# HYPOTHESIS: Output has 9s in grid cells that have markers, and 5 elsewhere (except landmarks = 4)
result = [[5 for _ in range(29)] for _ in range(22)]

# Fill landmark lines with 4
for h in [6, 17, 19]:
    for j in range(29):
        result[h][j] = 4
for v in [4, 13, 24, 28]:
    for i in range(22):
        result[i][v] = 4

# For each grid cell with marker, fill its interior with 9 (not landing lines)
for hi, vi in marker_cells:
    r_end = horiz_boundaries[hi+1] if hi+1 < len(horiz_boundaries) and horiz_boundaries[hi+1] not in [6, 17, 19] else horiz_boundaries[hi+1]
    r_start = horiz_boundaries[hi]
    c_end = vert_boundaries[vi+1] if vi+1 < len(vert_boundaries) and vert_boundaries[vi+1] not in [4, 13, 24, 28] else vert_boundaries[vi+1]
    c_start = vert_boundaries[vi]

    # Fill interior of this cell (not the sidelines which are landmarks)
    rows_to_fill = set()
    for r in range(r_start+1, r_end):
        if not (r in [6, 17, 19]):
            rows_to_fill.add(r)

    cols_to_fill = set()  
    for c in range(c_start+1, c_end):
        if not (c in [4, 13, 24, 28]):
            cols_to_fill.add(c)

    for r in rows_to_fill:
        for c in cols_to_fill:
            result[r][c] = 9

print(f"\nHYPOTHESIS: Fill grid cells with markers with 9s, landmarks = 4, rest = 5")
print(f"  Total 4s (landmarks): {sum(1 for row in result for cell in row if cell == 4)}")
print(f"  Total 9s: {sum(1 for row in result for cell in row if cell == 9)}")
print(f"  Total 5s: {sum(1 for row in result for cell in row if cell == 5)}")

# Print result
print("\nResult:")
for row in result:
    print(''.join(map(str, row)))

# Get the computed grid
horiz_lines = [6, 17, 19]
vert_lines = [4, 13, 24, 28]

marker_positions = [(3, 15), (10, 11), (16, 8), (18, 12)]

horiz_intervals = [(-1, 6), (6, 17), (17, 19), (19, 22)]
vert_intervals = [(-1, 4), (4, 13), (13, 24), (24, 28), (28, 29)]

marker_cells = {}
for r, c in marker_positions:
    hi = next(i for i, (h1, h2) in enumerate(horiz_intervals) if h1 < r < h2)
    vi = next(i for i, (v1, v2) in enumerate(vert_intervals) if v1 < c < v2)
    marker_cells[(hi, vi)] = marker_cells.get((hi, vi), 0) + 1

result = [[5 for _ in range(29)] for _ in range(22)]

for hi, (h1, h2) in enumerate(horiz_intervals):
    for vi, (v1, v2) in enumerate(vert_intervals):
        r_start = h1 if h1 not in horiz_lines else h1 + 1
        r_end = h2 if h2 not in horiz_lines else h2 - 1
        c_start = v1 if v1 not in vert_lines else v1 + 1
        c_end = v2 if v2 not in vert_lines else v2 - 1

        filler = 9 if marker_cells.get((hi, vi), 0) > 0 else 5

        for r in range(r_start, r_end + 1 if r_start <= r_end else r_start):
            for c in range(c_start, c_end + 1 if r_start <= r_end else c_start):
                if r < 22 and c < 29:
                    result[r][c] = filler

for h in horiz_lines:
    for j in range(29):
        result[h][j] = 4
for v in vert_lines:
    for i in range(22):
        if result[i][v] != 9:
            result[i][v] = 4

print("SOLUTION GRID:")
for row in result:
    print(''.join(map(str, row)))

# Counts
print(f"\nTotal: {sum(1 for row in result for cell in row if cell == 4)} 4s, {sum(1 for row in result for cell in row if cell == 9)} 9s, {sum(1 for row in result for cell in row if cell == 5)} 5s")

